from lib import *
S = SS('p66')
steps = [
    step("最简单的队列:worker 用 BRPOP 取任务,取出就从队列里删了。200 个任务、3 个 worker,第一个取到 t50 的 worker 处理它时被 kill -9:完成 199 个,队列里剩 0 个,丢失 1 个(t50),它既不在队列里、也没有完成,t50 只被开始处理过 1 次。取出和完成之间,任务只存在于那个 worker 的内存里,worker 一死就没了。", t=tl(S(1)), done=lidx(S(1), '200 个任务'), mark=lidx(S(1), '200 个任务'), b=bars([['任务总数', 200, '200'], ['完成', 199, '199'], ['丢失', 1, '1']], 200, done=[1], mark=[2]), kv=KV([['取任务', 'BRPOP,取出即删除'], ['worker 被 kill -9', '丢失 1 个任务 t50'], ['原因', '任务只在 worker 内存里']], ['原因'])),
    step("先把任务移到“正在处理”列表(BLMOVE queue → proc:<worker>),处理完再从该列表删除(ack)。t50 处理中途被杀:worker 结束后完成 199 个,队列剩 0 个,死掉的 worker 的列表里留着 ['t50'];由监控把它放回队列、w3 接手后完成 200 个,t50 开始处理了 2 次,全部任务共开始处理 201 次。t50 处理完、ack 之前被杀:完成数已是 200,列表里仍留着 t50,放回后又处理一次——同样 201 次。没有丢任务,代价是会重复:无法区分“没做完”和“做完了但没来得及 ack”。", t=tl(S(2)), done=lidx(S(2), '放回队列、w3 接手后'), mark=lidx(S(2), '死掉的 worker 的"正在处理"列表里留着'), b=bars([['任务总数', 200, '200'], ['完成', 200, '200'], ['开始处理的总次数', 201, '201']], 205, done=[1], mark=[2]), kv=KV([['任务丢失', '0 个'], ['t50 开始处理', '2 次'], ['做完但没 ack', '无法和没做完区分']], ['t50 开始处理'])),
    step("租约:取任务时在有序集合里记到期时间(租约 0.5 秒),监控每 0.1 秒把到期的任务放回队列,取任务用 Lua 脚本一次完成。(a) 某个 worker 处理 t5 时被杀:最终完成 10/10,丢失 0,t5 两次开始处理相隔 0.66 秒——不用知道是哪个 worker 死了,恢复至少要等一个租约。租约比任务时间短会怎样:t0 要处理 0.8 秒、租约 0.5 秒:(b) 不续约,只让 worker 跑 4 秒:t0 开始处理 5 次,监控放回 5 次——每次还没处理完租约就到期,任务被放回,做完又拿到它,没有尽头;(c) 处理期间每 0.2 秒续约一次:t0 只处理 1 次,放回 0 次;(d) 同 (b),但最多放回 3 次:t0 开始处理 3 次,放回 2 次,第三次到期进了 dead 列表。租约要比任务耗时长,或者让 worker 续约;还要有重试上限。", t=tl(S(3)), done=lidx(S(3), '(c) 同上'), mark=lidx(S(3), '(b) 租约 0.5 秒'), b=bars([['(a) 被杀后两次处理的间隔 秒', 0.66, '0.66'], ['(b) 不续约:开始处理次数', 5, '5'], ['(c) 续约:开始处理次数', 1, '1'], ['(d) 最多放回 3 次:开始处理次数', 3, '3']], 6, mark=[1], done=[0, 2, 3]), kv=KV([['(a) 租约恢复', '0.66 秒'], ['(b) 不续约', '4 秒内处理 5 次,没有尽头'], ['(c) 每 0.2 秒续约', '处理 1 次']], ['(c) 每 0.2 秒续约'])),
    step("取任务分两步(RPOP 再 ZADD 记租约),在两步之间崩溃(崩溃点是我注入的):最终完成 9/10,丢失 1 个 t3——它既不在队列里,也没有租约,监控找不到它。用 Lua 脚本一次完成“取出 + 记租约”,在脚本返回之后(开始处理之前)崩溃:完成 10/10,丢失 0,t3 靠租约到期被放回(监控放回 1 次)。两步之间的空隙里崩溃就会丢任务;脚本里没有这个空隙。", t=tl(S(4)), done=lidx(S(4), 'Lua 脚本一次完成'), mark=lidx(S(4), '两步取任务'), b=bars([['两步取任务:完成', 9, '9'], ['Lua 一次取任务:完成', 10, '10']], 10, mark=[0], done=[1]), kv=KV([['两步取任务', '崩溃在两步之间:丢 1 个'], ['Lua 脚本', '没有空隙:丢 0 个'], ['崩溃点', '是我注入的']], ['Lua 脚本'])),
    step("至少一次投递意味着同一个任务可能被处理多次。6 个任务、2 个 worker、租约 0.5 秒、t0 要处理 0.8 秒不续约、只让 worker 跑 3 秒:共开始处理 9 次(t0 占 4 次);不去重的副作用计数 8(最后一次开始处理的被我 3 秒到点终止,没做完);用“已处理集合”SADD 去重后副作用计数 6,等于不同任务数 6。副作用是“按任务 id 幂等”的(例如 INSERT … ON CONFLICT DO NOTHING)时,重复处理无害;不能幂等的副作用(发邮件、扣款)就要另外想办法。", t=tl(S(5)), done=lidx(S(5), '任务执行次数'), b=bars([['开始处理次数', 9, '9'], ['不去重的副作用', 8, '8'], ['SADD 去重后的副作用', 6, '6']], 10, mark=[1], done=[2]), kv=KV([['t0 开始处理', '4 次'], ['不去重', '副作用 8 次'], ['按任务 id 去重', '副作用 6 次 = 6 个任务']], ['按任务 id 去重'])),
    step("毒任务:处理 t7 必然让 worker 崩溃。没有重试上限:4.4 秒内(我给的时间上限 4 秒)worker 因 t7 崩溃 7 次,t7 开始处理 7 次,其他 9 个任务都完成了,dead 列表是空的——每次租约到期它又被放回队列,会一直崩下去。最多放回 3 次:2.6 秒内崩溃 3 次,t7 进了 dead 列表,队列清空,其他 9 个任务完成。没有上限,一个毒任务会不断杀死 worker。", t=tl(S(6)), done=lidx(S(6), '最多 3 次'), mark=lidx(S(6), '没有重试上限'), b=bars([['没有上限:worker 崩溃次数', 7, '7'], ['上限 3 次:worker 崩溃次数', 3, '3']], 8, mark=[0], done=[1]), kv=KV([['没有上限', '4 秒内崩溃 7 次,不会结束'], ['上限 3 次', '崩溃 3 次,t7 进 dead 列表'], ['其他任务', '都完成了(9 个)']], ['上限 3 次'])),
]
A = mkartp('p66', 66, '爬虫,Redis,任务队列,租约,至少一次,Lua,kill -9,Python,真实验证,动画演示',
    '在本机独立的 redis-server 上实测任务队列的崩溃恢复:BRPOP 取出就丢、BLMOVE 加 ack 不丢但会重复、租约到期自动放回、租约比任务短会无限重复、取任务分两步会在空隙里丢任务、毒任务要有重试上限。',
    '爬虫的任务队列放在 Redis 里,worker 崩溃了正在处理的任务去哪了?这篇在本机一个独立的 redis-server 上,用 kill -9 逐个试 BRPOP、BLMOVE 加 ack、租约三种取任务方式,以及租约、去重、毒任务这些配套的坑。',
    [('1 个', '用 BRPOP 取任务时,worker 被 kill -9,丢失的任务数(200 个任务里)'), ('201 对 200', '用 BLMOVE + ack 时,全部任务开始处理的总次数与任务数(多出的 1 次是重复)'), ('5 次', '租约 0.5 秒、任务 0.8 秒不续约时,同一个任务在 4 秒内被开始处理的次数')],
    [('取出就删', '<p>用 BRPOP 取任务,任务一出队就只存在于 worker 的内存里。worker 被 kill -9,这个任务就丢了(实验里 200 个任务丢 1 个)。</p>'),
     ('先移再确认', '<p>把任务移进“正在处理”列表,做完再删除,崩溃时任务还在那个列表里,可以放回队列。代价是可能重复:无法区分“没做完”和“做完了没来得及 ack”,两种情况下实验里都是 201 次开始处理。</p>'),
     ('租约', '<p>取任务时记一个到期时间,监控把到期的任务放回队列,就不用知道哪个 worker 死了。恢复至少要等一个租约(实验里 0.66 秒,租约 0.5 秒)。</p>'),
     ('租约要比任务长,或者续约', '<p>租约比任务耗时短又不续约,任务做完之前就被放回,每次都被重新取走,没有尽头(实验里 4 秒内被处理 5 次)。worker 处理期间定期续约,或者限制最多放回次数,都能收住。</p>'),
     ('取任务要原子', '<p>取任务和记租约分两个命令,中间崩溃任务就丢了(实验里注入崩溃,丢 t3)。用 Lua 脚本在 Redis 里一次做完。</p>'),
     ('重复处理与毒任务', '<p>至少一次投递会重复处理,副作用要按任务 id 幂等(实验里去重后副作用数等于不同任务数)。处理时必然崩溃的毒任务没有重试上限就会不断杀死 worker(4 秒内 7 次),要有上限并放进 dead 列表。</p>')],
    steps,
    [ENV_P + '。redis-server 8.10.2 独立实例(只监听 127.0.0.1 的 9700 以上端口,关闭持久化,实验后关闭;没有碰本机已有的 Redis),redis-py 8.0.1;worker 是独立的 Python 进程,崩溃是用 SIGKILL 杀掉自己(在指定任务处,每个崩溃点只触发一次,毒任务除外);监控和续约在父进程或线程里;带时间上限的情形(第三节 (b)、第五节、第六节没有上限那组)是我到点终止 worker,所以次数是“上限内”的次数;各情形跑一次',
     '没有验证:Redis Streams(XREADGROUP、XAUTOCLAIM)等内置的消费者组机制;Redis 主从或集群切换时的丢任务;持久化(AOF/RDB)打开时的行为;租约用客户端时钟还是 Redis 时钟(这里的到期时间用 Redis 的 TIME);worker 与 Redis 之间网络分区时的行为;大量任务时 ZRANGEBYSCORE 扫描的开销;worker 被杀的时刻在“取出”与“处理”之间的所有可能崩溃点(只测了几个)'],
    'Redis 任务队列租约')
